package br.com.portal.controller;
import br.com.portal.dto.*; import br.com.portal.model.Aluno; import br.com.portal.service.AlunoService; import jakarta.servlet.http.HttpSession; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/alunos") public class AlunoController {private final AlunoService s;public AlunoController(AlunoService s){this.s=s;}
 @GetMapping("/turma/{turmaId}") List<Aluno> listar(@PathVariable Long turmaId,HttpSession x){return s.listar(turmaId,x);} @GetMapping("/{id}") Aluno buscar(@PathVariable Long id,HttpSession x){return s.buscar(id,x);} @PostMapping("/turma/{turmaId}") ResponseEntity<Aluno> criar(@PathVariable Long turmaId,@Valid @RequestBody AlunoRequest r,HttpSession x){return ResponseEntity.status(201).body(s.criar(turmaId,r,x));} @PutMapping("/{id}") Aluno atualizar(@PathVariable Long id,@Valid @RequestBody AlunoRequest r,HttpSession x){return s.atualizar(id,r,x);} @DeleteMapping("/{id}") ResponseEntity<Void> excluir(@PathVariable Long id,HttpSession x){s.excluir(id,x);return ResponseEntity.noContent().build();}}
